3	import org.jspecify.annotations.NonNull;
4	import org.jspecify.annotations.Nullable;
5	import org.mapstruct.Mapper;
6	import org.mapstruct.Mapping;
7	import org.springframework.data.domain.Page;
8	import org.springframework.samples.petclinic.model.Owner;
9	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
11	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
12	
13	import java.util.Collection;
14	import java.util.List;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
25	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
26	    @Mapping(target = "locality", expression = "java(locality(owner))")
27	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
28	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /**
32	     * Derives the owner's duplicate-detection {@code identityKey}, formatted as
33	     * {@code normalizedTelephone + '|' + email + '|' + householdId} with an empty email segment when
34	     * the owner has no email. This is the same key the create endpoint uses to reject an owner whose
35	     * whole key equals an existing owner's.
36	     */
37	    default @Nullable String identityKey(@Nullable Owner owner) {
38	        if (owner == null) {
39	            return null;
40	        }
41	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
42	        String email = owner.getEmail() == null ? "" : owner.getEmail();
43	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
44	        return telephone + "|" + email + "|" + householdId;
45	    }
46	
47	    /**
48	     * Derives the owner's preferred contact channel: {@code EMAIL} when an email is present,
49	     * otherwise {@code PHONE}.
50	     */
51	    default OwnerDto.@Nullable ContactPreferenceEnum contactPreference(@Nullable Owner owner) {
52	        if (owner == null) {
53	            return null;
54	        }
55	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
56	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
57	    }
58	
59	    /**
60	     * Canonical region -> city table, used to derive an owner's locality.
61	     */
62	    java.util.Map<String, String> CITY_REGION = java.util.Map.of(
63	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
64	
65	    /**
66	     * Canonical region -> inclusive 4-digit postcode range {low, high}, used to derive an
67	     * owner's locality from the postcode (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
68	     */
69	    java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
70	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
71	
72	    /**
73	     * Derives the owner's locality, preferring the postcode: the region whose range contains the
74	     * postcode (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) wins. When the postcode is absent or in
75	     * no known range, falls back to the fixed city-to-region table (Sydney->NSW, Melbourne->VIC,
76	     * Brisbane->QLD). Returns the canonical region string, or {@code 'UNKNOWN'} when neither resolves.
77	     */
78	    default @Nullable String locality(@Nullable Owner owner) {
79	        if (owner == null) {
80	            return null;
81	        }
82	        String fromPostcode = regionFromPostcode(owner.getPostcode());
83	        if (fromPostcode != null) {
84	            return fromPostcode;
85	        }
86	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
87	    }
88	
89	    /**
90	     * Returns the canonical region whose inclusive postcode range contains the given 4-digit
91	     * postcode, or {@code null} when the postcode is absent, non-numeric, or in no known range.
92	     */
93	    private @Nullable String regionFromPostcode(@Nullable String postcode) {
94	        if (postcode == null) {
95	            return null;
96	        }
97	        int code;
98	        try {
99	            code = Integer.parseInt(postcode.trim());
100	        }
101	        catch (NumberFormatException e) {
102	            return null;
103	        }
104	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
105	            int[] range = entry.getValue();
106	            if (code >= range[0] && code <= range[1]) {
107	                return entry.getKey();
108	            }
109	        }
110	        return null;
111	    }
112	
113	    /**
114	     * Returns the owner's numeric membership level from 1 to 3, computed on creation: starting at 1,
115	     * adding 1 when an email is present and adding 1 when namesakeCount is 0, capped at 3 (level 4 is
116	     * reserved for tenure).
117	     */
118	    default @Nullable Integer membershipLevel(@Nullable Owner owner) {
119	        if (owner == null) {
120	            return null;
121	        }
122	        int level = 1;
123	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
124	        if (hasEmail) {
125	            level++;
126	        }
127	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
128	        if (noNamesakes) {
129	            level++;
130	        }
131	        return Math.min(level, 3);
132	    }
133	
134	    /**
135	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the
136	     * last two digits of the registrationDate year, e.g. {@code 'MEL-SMI-0007-M26'}.
137	     */
138	    default @Nullable String membershipNumber(@Nullable Owner owner) {
139	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
140	            return null;
141	        }
142	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
143	    }
144	
145	    /**
146	     * Formats an owner's stored names as {@code 'LastName, FirstName'}.
147	     */
148	    default @Nullable String displayName(@Nullable Owner owner) {
149	        if (owner == null) {
150	            return null;
151	        }
152	        return owner.getLastName() + ", " + owner.getFirstName();
153	    }
154	
155	    /**
