157	     * lastName, dot-separated with a trailing dot, e.g. {@code 'J.S.'}.
158	     */
159	    default @Nullable String initials(@Nullable Owner owner) {
160	        if (owner == null) {
161	            return null;
162	        }
163	        StringBuilder sb = new StringBuilder();
164	        String firstName = owner.getFirstName();
165	        if (firstName != null && !firstName.isEmpty()) {
166	            sb.append(Character.toUpperCase(firstName.charAt(0))).append('.');
167	        }
168	        String lastName = owner.getLastName();
169	        if (lastName != null && !lastName.isEmpty()) {
170	            sb.append(Character.toUpperCase(lastName.charAt(0))).append('.');
171	        }
172	        return sb.toString();
